  ["BUTTON_LAG_AUCTIONHOUSE"] = { "Casa d'aste", 0x465b376b, "." },
  ["BUYBACK"] = { "Riacquista", 0xe2bf2622, "." },
  ["BUYOUT"] = { "Acquisto", 0xee33cde0, "." },
  ["BUYOUT_AUCTION_CONFIRMATION"] = { "Acquista per:", 0x6b83028d, "." },
  ["BUY_GUILDBANK_TAB"] = { "Acquista una nuova scheda della banca di gilda", 0x345c0a0e, "." },
  ["BY_SOURCE"] = { "Per fonte", 0x46c54c7a, "." },
  ["BY_SOURCE_COMBATLOG_TOOLTIP"] = { "Colore basato sull'incantatore.", 0x3e1cd603, "." },
  ["BY_TARGET"] = { "Per bersaglio", 0x4c1fd688, "." },
  ["BY_TARGET_COMBATLOG_TOOLTIP"] = { "Colore basato sul bersaglio.", 0x2aaf0ff6, "." },
  ["BroadcastText:316345"] = { "Per migliaia di anni,", 0x86db738c, "." },
  ["BroadcastText:316346"] = { "un gruppo di alti elfi in esilio è rimasto al sicuro", 0xe55ad36f, "." },
  ["BroadcastText:316348"] = { "e nascosto sul proprio santuario volante, Zephras Isle.", 0x4372a431, "." },
  ["BroadcastText:316349"] = { "Questi \"Skyborne\", come chiamano se stessi,", 0x8aa20a25, "." },
  ["BroadcastText:316350"] = { "condividevano un legame con gli elementali dell'aria", 0x55115e31, "." },
  ["BroadcastText:316351"] = { "che tenevano sospesa la loro isola nel reame di Celaria.", 0xddc29d35, "." },
  ["BroadcastText:316352"] = { "Ma negli ultimi anni", 0xf7157c63, "." },
  ["BroadcastText:316353"] = { "gli elementali sono scomparsi senza lasciare traccia,", 0xe44574f1, "." },
  ["BroadcastText:316354"] = { "turbando la delicata magia che li proteggeva nel loro rifugio tra le nuvole.", 0x68b82607, "." },
  ["BroadcastText:316355"] = { "Ora una nuova generazione di elfi Skyborne affronta un'epoca di cambiamenti senza precedenti", 0x5277c225, "." },
  ["BroadcastText:316356"] = { "e deve cercare nuovi alleati e nuove fonti di magia", 0x72650d43, "." },
  ["BroadcastText:316358"] = { "per proteggere la propria patria nascosta e garantirsi un futuro...", 0xa97fa88e, "." },
  ["BroadcastText:329279"] = { "Gli eccentrici gnomi, spesso geniali, sono considerati una delle razze più bizzarre del mondo.", 0xdcebe743, "." },
  ["BroadcastText:329280"] = { "Con la loro ossessione per lo sviluppo di nuove tecnologie rivoluzionarie e la costruzione di sbalorditive meraviglie d'ingegneria, è un miracolo che qualche gnomo sia sopravvissuto abbastanza a lungo da prosperare.", 0xef45019c, "." },
  ["BroadcastText:329281"] = { "Nel corso degli anni gli gnomi hanno fornito armi ingegnose per aiutare la Grande Alleanza nelle sue feroci battaglie contro l'Orda.", 0xb517dde4, "." },
  ["BroadcastText:329282"] = { "Prosperando nella meravigliosa città tecnologica di Gnomeregan, gli gnomi condividono le risorse delle vette boscose di Dun Morogh con i loro cugini nani.", 0x9cdefa76, "." },
  ["BroadcastText:329283"] = { "Di recente, però, una minaccia barbarica è emersa dalle viscere della terra e ha invaso Gnomeregan.", 0x4481ed47, "." },
  ["BroadcastText:329284"] = { "Con l'aiuto dei loro alleati nani, gli gnomi hanno combattuto valorosamente per salvare la loro amata città.", 0x166fd447, "." },
  ["BroadcastText:329285"] = { "Ciononostante, Gnomeregan è andata perduta per sempre.", 0xa34d8bb8, "." },
  ["BroadcastText:329286"] = { "Gli gnomi sopravvissuti hanno trovato rifugio nella roccaforte nanica di Forgiardente.", 0x196a0db0, "." },
  ["BroadcastText:329287"] = { "Lì sono rimasti, escogitando strategie per riconquistare la loro città.", 0x53c6ac4a, "." },
  ["BroadcastText:329288"] = { "Come gnomo di nobile rango, spetta a te raccogliere la sfida e guidare il tuo popolo curioso verso un futuro migliore.", 0x3cb9a935, "." },
  ["BroadcastText:329301"] = { "Gli stoici nani di Forgiardente hanno passato innumerevoli generazioni a estrarre tesori dalle profondità della terra.", 0x00b7c3df, "." },
  ["BroadcastText:329302"] = { "Nascosti nella loro inespugnabile roccaforte nella montagna di Forgiardente, di rado si avventuravano oltre le vette invernali di Dun Morogh.", 0xb25198f6, "." },
  ["BroadcastText:329303"] = { "Di recente, però, i nani hanno portato alla luce una serie di rovine che custodivano i segreti della loro antica eredità.", 0x6b2fb894, "." },
  ["BroadcastText:329304"] = { "Deciso a scoprire la verità sulle leggendarie origini del suo popolo, il grande re Magni Bronzebeard ha ordinato ai nani di passare dall'estrazione mineraria all'archeologia.", 0x314e1092, "." },
  ["BroadcastText:329305"] = { "Come parte della Grande Alleanza, i valorosi eserciti nanici sono stati chiamati a combattere la spietata Orda in terre lontane.", 0x273de2b6, "." },
  ["BroadcastText:329306"] = { "In questi tempi pericolosi, la difesa del regno della montagna spetta a nani coraggiosi come te.", 0xe059bcd5, "." },
  ["BroadcastText:329307"] = { "Gli spiriti degli antichi re vegliano su di te, e le montagne stesse sono la tua forza.", 0xd4ea9c5a, "." },
  ["BroadcastText:329308"] = { "Il futuro del tuo popolo è nelle tue mani.", 0xc4bd84e0, "." },
  ["BroadcastText:329309"] = { "I nobili umani di Roccavento sono una razza fiera e tenace.", 0xb42dee52, "." },
  ["BroadcastText:329310"] = { "Sebbene la recente invasione della demoniaca Legione Infuocata abbia decimato il loro regno fratello di Lordaeron, i difensori di Roccavento vegliano contro chiunque minacci la sacralità delle loro terre.", 0xa62b9ce4, "." },
  ["BroadcastText:329311"] = { "Adagiata ai piedi delle colline della Foresta di Elwynn, la città di Roccavento è uno degli ultimi bastioni del potere umano nel mondo.", 0x17836a8c, "." },
  ["BroadcastText:329312"] = { "Governato dal giovane re Anduin Wrynn, il popolo di Roccavento resta fedele al suo impegno verso la Grande Alleanza.", 0x634f32b6, "." },
  ["BroadcastText:329313"] = { "Sostenuti dai loro fedeli alleati, gli eserciti di Roccavento sono stati chiamati a combattere l'Orda selvaggia su campi di battaglia lontani.", 0x23b6ef77, "." },
  ["BroadcastText:329314"] = { "Con gli eserciti lontani, la difesa di Roccavento spetta ora ai suoi fieri cittadini.", 0xff38b256, "." },
  ["BroadcastText:329315"] = { "Devi difendere il regno dai luridi bastardi che lo minacciano e dare la caccia ai traditori sovversivi che cercano di distruggerlo dall'interno.", 0xa0734a9a, "." },
  ["BroadcastText:329316"] = { "Questo è il tempo degli eroi.", 0x9555fcdd, "." },
  ["BroadcastText:329317"] = { "Ora può essere narrato il capitolo più grande dell'umanità.", 0x5db460cd, "." },
  ["BroadcastText:329318"] = { "Per 10.000 anni gli immortali elfi della notte hanno coltivato una società druidica nei recessi ombrosi della foresta di Valtetra.", 0x6c1cbbbf, "." },
  ["BroadcastText:329319"] = { "Di recente, però, la catastrofica invasione della Legione Infuocata ha infranto la quiete della loro antica civiltà.", 0x9c08e260, "." },
  ["BroadcastText:329320"] = { "Guidati dall'arcidruido Malfurion Stormrage e dalla sacerdotessa Tyrande Whisperwind, i potenti elfi della notte si sono sollevati contro l'assalto demoniaco.", 0x934627b3, "." },
  ["BroadcastText:329321"] = { "Pur vittoriosi, gli elfi della notte sono stati costretti a sacrificare la loro preziosa immortalità e a veder bruciare le loro amate foreste.", 0xd7ce0f80, "." },
  ["BroadcastText:329322"] = { "Nel tentativo di riconquistare l'immortalità, alcuni druidi ribelli hanno cospirato per piantare un albero speciale che legasse i loro spiriti al mondo eterno.", 0xd010eb14, "." },
  ["BroadcastText:329323"] = { "Nonostante Malfurion li avesse avvertiti che la natura non avrebbe mai benedetto un atto così egoista, i druidi piantarono il Grande Albero, Teldrassil, al largo delle coste tempestose di Kalimdor.", 0x257f885f, "." },
  ["BroadcastText:329324"] = { "Tra i rami del colossale albero mise radici la meravigliosa città di Darnassus.", 0x0e36ddfd, "." },
  ["BroadcastText:329325"] = { "Tuttavia, il Grande Albero non era stato consacrato dalla benedizione della natura e cadde presto preda della corruzione della Legione Infuocata.", 0x31f33710, "." },
  ["BroadcastText:329326"] = { "Ora la fauna selvatica, e perfino i rami del Grande Albero stesso, sono contaminati da un'oscurità crescente.", 0x04f0b8fd, "." },
  ["BroadcastText:329327"] = { "Come uno dei pochi elfi della notte rimasti al mondo, hai giurato di difendere Darnassus e i figli selvaggi della natura dalla corruzione strisciante della Legione.", 0xfb0fecd7, "." },
  ["BroadcastText:329328"] = { "Molto tempo fa, l'Orda degli orchi fu corrotta dalla Legione Infuocata e attirata nel mondo di Azeroth.", 0xe399c45b, "." },
  ["BroadcastText:329329"] = { "Per generazioni gli orchi mossero guerra ai regni umani di Roccavento e Lordaeron.", 0x5ed323e6, "." },
  ["BroadcastText:329330"] = { "Sebbene l'Orda fosse stata infine sconfitta, un giovane e lungimirante capoguerra di nome Thrall si fece avanti per guidare il suo popolo nell'ora più buia.", 0x4eaf3518, "." },
  ["BroadcastText:329331"] = { "Sotto la guida di Thrall, gli orchi si liberarono dalle catene della corruzione demoniaca e riscoprirono la loro eredità sciamanica.", 0xfa0e920e, "." },
  ["BroadcastText:329332"] = { "Dopo anni di peregrinazioni, gli orchi fondarono il loro regno nelle aspre lande desolate di Durotar.", 0xec4d85c8, "." },
  ["BroadcastText:329333"] = { "Dalla città guerriera di Orgrimmar sono pronti a distruggere chiunque osi sfidare la loro supremazia.", 0x31cd3c28, "." },
  ["BroadcastText:329334"] = { "Come fiero difensore di Durotar, è tuo dovere annientare i tuoi nemici, visibili e invisibili, perché i loschi agenti della Legione Infuocata vagano ancora per queste terre.", 0x708df6a9, "." },
  ["BroadcastText:329335"] = { "Un tempo popolo nomade, i tauren percorrono le sconfinate pianure delle Savane, cacciando i possenti kodo.", 0x8c0ce30c, "." },
  ["BroadcastText:329336"] = { "Sparse per le terre, le tribù erranti erano unite solo dall'odio comune verso il loro nemico giurato: i centauri predoni.", 0x551112c1, "." },
  ["BroadcastText:329337"] = { "In cerca di aiuto contro i centauri, il grande capo Cairne Bloodhoof strinse amicizia con i selvaggi orchi da poco giunti a Kalimdor.", 0xa1032da1, "." },
  ["BroadcastText:329338"] = { "Con l'aiuto degli orchi, Cairne e la sua tribù riuscirono a respingere i centauri e a fare proprie le praterie di Mulgore.", 0xaa0bb444, "." },
  ["BroadcastText:329339"] = { "Sull'altopiano spazzato dal vento del Picco del Tuono, Cairne costruì un rifugio per il suo popolo.", 0x52a83553, "." },
  ["BroadcastText:329340"] = { "Col tempo, le tribù sparse si unirono sotto un unico stendardo.", 0x23fbbc57, "." },
  ["BroadcastText:329341"] = { "Sebbene i nobili tauren siano pacifici per natura, i riti della grande caccia sono venerati come il cuore della loro cultura spirituale.", 0xb19247fa, "." },
})
